lag > 60 E (tentativas < 3 OU emergencia)

// regra de bolso: na dúvida, parênteses. Clareza vence economia.

FUNÇÃO classificar(lag, limite) -> texto
  // ENTRADA: lag (inteiro ou NULO), limite (inteiro)
  // SAÍDA: 'OK' | 'ALERTA' | 'PARADA'
  // Não lê rede, não escreve disco: só decide. (função pura)
  SE lag É NULO ENTÃO RETORNAR 'PARADA'
  SE lag > limite ENTÃO RETORNAR 'ALERTA'
  RETORNAR 'OK'
FIM-FUNÇÃO

// quem chama: status = classificar(300, 60)  -> 'ALERTA'

// O(n): uma passada por host — dobra o fleet, dobra o tempo
PARA cada host EM fleet FAÇA        // N voltas
  checar(host)                       // custo fixo
FIM-PARA                             // total ~ N operações

// O(n²): cada host comparado com todos — 100 hosts = 10.000 pares
PARA cada a EM fleet FAÇA            // N voltas
  PARA cada b EM fleet FAÇA          // N voltas de novo
    comparar(a, b)
  FIM-PARA
FIM-PARA                             // total ~ N x N operações

